/**
 * Unit tests for the dashboard password KDF.
 *
 * The Python fixtures below were generated with the oracle
 * `servermanage/security.py` (`hashlib.pbkdf2_hmac("sha256", pw, salt, 200000)`,
 * hex digest + hex salt) and are embedded verbatim so these tests prove the
 * Node implementation is byte-compatible with Python in both directions.
 */
import { describe, expect, it } from 'vitest';

import {
  PBKDF2_ALGORITHM,
  PBKDF2_ITERATIONS,
  SALT_BYTES,
  hashPassword,
  verifyPassword,
} from '../../../src/web/security/password';

// Generated by CPython:
//   hashlib.pbkdf2_hmac("sha256", "correct horse battery staple",
//                        bytes.fromhex("000102030405060708090a0b0c0d0e0f"), 200000).hex()
const PY_SALT_HEX = '000102030405060708090a0b0c0d0e0f';
const PY_HASH_HEX = '45fea9d79f583c568d79d99c35c95c34f9603a5fbd4f8dd36adf6453724b79c8';
const PY_PASSWORD = 'correct horse battery staple';

// Generated by CPython:
//   hashlib.pbkdf2_hmac("sha256", "密码测试",
//                        bytes.fromhex("aa" * 16), 200000).hex()
const PY_UNICODE_SALT_HEX = 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa';
const PY_UNICODE_HASH_HEX = '1ec89a649805bd329b8c9225aad2447fe2d20e1736bac8a6d112eb0f06ccc5c5';
const PY_UNICODE_PASSWORD = '密码测试';

// Produced by the live oracle at test-authoring time:
//   servermanage.security.hash_password('interop-pass') ->
//   (hash_hex, salt_hex)
const ORACLE_HASH_HEX = '69e9f71716b38b08eca5056da12e89338ced62012eb056154491236f841ca0cd';
const ORACLE_SALT_HEX = '286de0e50cfdf4d382a888e09969f445';

describe('constants', () => {
  it('match the Python oracle', () => {
    expect(PBKDF2_ITERATIONS).toBe(200000);
    expect(SALT_BYTES).toBe(16);
    expect(PBKDF2_ALGORITHM).toBe('PBKDF2-SHA256');
  });
});

describe('hashPassword', () => {
  it('returns a well-formed record', () => {
    const result = hashPassword('s3cret');
    expect(result).toMatchObject({ iterations: 200000, algorithm: PBKDF2_ALGORITHM });
    expect(result.hash).toMatch(/^[0-9a-f]{64}$/);
    expect(result.salt).toMatch(/^[0-9a-f]{32}$/);
    expect(Buffer.from(result.salt, 'hex')).toHaveLength(16);
  });

  it('uses a fresh random salt each call', () => {
    const a = hashPassword('same');
    const b = hashPassword('same');
    expect(a.salt).not.toBe(b.salt);
    expect(a.hash).not.toBe(b.hash);
  });

  it('reproduces the Python digest for a fixed salt (byte-for-byte compatible)', () => {
    const result = hashPassword(PY_PASSWORD, {
      salt: Buffer.from(PY_SALT_HEX, 'hex'),
      iterations: 200000,
    });
    expect(result.hash).toBe(PY_HASH_HEX);
    expect(result.salt).toBe(PY_SALT_HEX);
  });

  it('reproduces the Python digest for a non-ASCII password', () => {
    const result = hashPassword(PY_UNICODE_PASSWORD, {
      salt: Buffer.from(PY_UNICODE_SALT_HEX, 'hex'),
      iterations: 200000,
    });
    expect(result.hash).toBe(PY_UNICODE_HASH_HEX);
  });

  it('rejects non-string input', () => {
    // @ts-expect-error deliberately wrong type
    expect(() => hashPassword(123)).toThrow(TypeError);
  });
});

describe('verifyPassword', () => {
  const stored = hashPassword('correct horse battery staple');

  it('accepts the correct password and round-trips', () => {
    expect(verifyPassword('correct horse battery staple', stored)).toBe(true);
  });

  it('rejects a wrong password', () => {
    expect(verifyPassword('Correct horse battery staple', stored)).toBe(false);
    expect(verifyPassword('', stored)).toBe(false);
  });

  it('verifies Python-generated hashes', () => {
    expect(
      verifyPassword(PY_PASSWORD, {
        hash: PY_HASH_HEX,
        salt: PY_SALT_HEX,
        iterations: 200000,
      }),
    ).toBe(true);
    expect(
      verifyPassword('wrong', {
        hash: PY_HASH_HEX,
        salt: PY_SALT_HEX,
        iterations: 200000,
      }),
    ).toBe(false);
    expect(
      verifyPassword(PY_UNICODE_PASSWORD, {
        hash: PY_UNICODE_HASH_HEX,
        salt: PY_UNICODE_SALT_HEX,
        iterations: 200000,
      }),
    ).toBe(true);
  });

  it('verifies a hash emitted by the live Python oracle', () => {
    expect(
      verifyPassword('interop-pass', {
        hash: ORACLE_HASH_HEX,
        salt: ORACLE_SALT_HEX,
        iterations: 200000,
      }),
    ).toBe(true);
    expect(
      verifyPassword('interop-pass!', {
        hash: ORACLE_HASH_HEX,
        salt: ORACLE_SALT_HEX,
        iterations: 200000,
      }),
    ).toBe(false);
    // ...and re-deriving with the same salt reproduces the oracle's digest.
    expect(hashPassword('interop-pass', { salt: Buffer.from(ORACLE_SALT_HEX, 'hex'), iterations: 200000 }).hash).toBe(
      ORACLE_HASH_HEX,
    );
  });

  it('tolerates extra fields such as username', () => {
    expect(
      verifyPassword(PY_PASSWORD, {
        username: 'admin',
        hash: PY_HASH_HEX,
        salt: PY_SALT_HEX,
        iterations: 200000,
      }),
    ).toBe(true);
  });

  it('returns false for malformed stored records instead of throwing', () => {
    expect(verifyPassword('x', null)).toBe(false);
    expect(verifyPassword('x', undefined)).toBe(false);
    expect(verifyPassword('x', { hash: '', salt: '', iterations: 200000 })).toBe(false);
    expect(verifyPassword('x', { hash: 'zz', salt: PY_SALT_HEX, iterations: 200000 })).toBe(false);
    expect(verifyPassword('x', { hash: PY_HASH_HEX.slice(1), salt: PY_SALT_HEX, iterations: 200000 })).toBe(false);
    expect(verifyPassword('x', { hash: PY_HASH_HEX, salt: PY_SALT_HEX, iterations: 0 })).toBe(false);
    expect(verifyPassword('x', { hash: PY_HASH_HEX, salt: PY_SALT_HEX, iterations: -1 })).toBe(false);
    expect(verifyPassword('x', { hash: PY_HASH_HEX, salt: PY_SALT_HEX, iterations: 200000.5 })).toBe(false);
  });

  it('returns false for a non-string password', () => {
    // @ts-expect-error deliberately wrong type
    expect(verifyPassword(42, stored)).toBe(false);
  });

  it('does not accept a hash with the right prefix but wrong length', () => {
    expect(verifyPassword(PY_PASSWORD, { hash: PY_HASH_HEX.slice(0, 32), salt: PY_SALT_HEX, iterations: 200000 })).toBe(false);
  });
});
